import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import * as Icons from "lucide-react";

import { tasks } from "@/lib/api";
import { must } from "@/lib/backend";
import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";

import { submit } from "./actions";
import Form from "./form";

export const metadata: Metadata = { title: "Complete" };

export default function Page() {
    return (
        <main className="flex flex-1 flex-col">
            <PageBody
                title={"Complete"}
                content={(className) => (
                    <div className={className}>
                        <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                            <Loaded />
                        </Suspense>
                    </div>
                )}
            />
        </main>
    );
}

// Loaded fills the form once its record and choices are in.
async function Loaded() {
    await connection();
    const options = {
        task: (await must(tasks.list())).map((r) => ({ id: r.id, label: r.title })),
    };
    return <Form action={submit} initial={{}} options={options} />;
}

type PageBodyProps = {
    title: string;
    content: (className: string) => React.ReactNode;
};

function PageBody({ title, content }: PageBodyProps): React.ReactNode {
    return (
      <div className="mx-auto flex w-full max-w-2xl flex-col gap-6 px-4 py-8 sm:px-6 md:py-12">
        <header className="flex flex-col gap-2">
          <div className="flex items-center gap-3">
            <div className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-primary text-primary-foreground">
              <Icons.CircleCheck className="size-5" />
            </div>
            <h1 className="font-heading text-2xl font-semibold tracking-tight text-foreground md:text-3xl">
              {title}
            </h1>
          </div>
          <p className="text-sm text-muted-foreground">
            Fill in the fields below and save to submit.
          </p>
        </header>
        <Separator orientation="horizontal" />
        {content("flex w-full flex-col gap-6 rounded-xl border bg-card p-4 text-card-foreground sm:p-6")}
      </div>
    );
}
